        boolean swapped;
        for (int I = 0; I < size - 1; i++) {
            swapped = false;
            for (int j = 0; j < size - I - 1; j++) {
                if (arr[j] > arr[j+1]) {
                    int temp = arr[j];
                    arr[j] = arr[j+1];
                    arr[j+1] = temp;
                    swapped = true;
                }
            }
            if (swapped == false) {
                break;
            }
